// Verified provider time series are separate from visitor-entered asking records.
window.renderAskingHistory=function(a){
 const root=document.getElementById('asking-history');if(!root)return;
 const record=window.PROVIDER_HISTORY?.[a.id];
 root.innerHTML='<div class="market-top"><h3>최근 10년 가격 변동 · 네이버 / KB</h3><select id="provider-period" aria-label="시세 비교 기간"><option value="10">최근 10개년</option><option value="1">최근 1년</option></select></div><div id="provider-content"></div>';
 const period=document.getElementById('provider-period');
 function draw(){
  const years=Number(period.value),end=Date.parse(today()+'T00:00:00Z'),year=Number(today().slice(0,4)),start=years===10?Date.UTC(year-9,0,1):end-365*86400000;
  const series=[{id:'naver',name:'네이버',color:'#d27b2b'},{id:'kb',name:'KB',color:'#8052b3'}].map(s=>({...s,...record?.[s.id],rows:(record?.[s.id]?.rows||[]).filter(r=>Date.parse(r.date+'T00:00:00Z')>=start&&Date.parse(r.date+'T00:00:00Z')<=end).sort((x,y)=>x.date.localeCompare(y.date))}));
  const all=series.flatMap(s=>s.rows),vals=all.map(r=>r.price),min=vals.length?Math.min(...vals):0,max=vals.length?Math.max(...vals):1,pad=Math.max((max-min)*.15,.25),lo=Math.max(0,min-pad),hi=max+pad;
  const x=d=>64+(Date.parse(d+'T00:00:00Z')-start)/(end-start)*530,y=v=>190-(v-lo)/(hi-lo)*150;
  let grid='';for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4;grid+='<line x1="64" x2="594" y1="'+y(v)+'" y2="'+y(v)+'" stroke="#dfe8ec"/><text x="54" y="'+(y(v)+4)+'" text-anchor="end">'+v.toFixed(1)+'</text>';}
  const lines=series.map(s=>'<g data-provider="'+s.id+'">'+(s.rows.length>1?'<polyline fill="none" stroke="'+s.color+'" stroke-width="3" points="'+s.rows.map(r=>x(r.date)+','+y(r.price)).join(' ')+'"/>':'')+s.rows.map(r=>'<circle tabindex="0" data-provider-point="'+s.id+'" data-date="'+r.date+'" cx="'+x(r.date)+'" cy="'+y(r.price)+'" r="3" fill="'+s.color+'"><title>'+s.name+' · '+esc(r.period||r.date)+' · '+money(r.price)+'</title></circle>').join('')+'</g>').join('');
  const ticks=years===10?Array.from({length:10},(_,i)=>({date:(year-9+i)+'-01-01',label:String(year-9+i)})):[{date:new Date(start).toISOString().slice(0,10),label:new Date(start).toISOString().slice(0,7)},{date:today(),label:today().slice(0,7)}];
  const chart='<svg class="market-chart" viewBox="0 0 660 245" role="img" aria-label="네이버와 KB의 실제 확보 시세 추이"><text x="20" y="22">억원</text>'+grid+lines+ticks.map(t=>'<text x="'+x(t.date)+'" y="221" text-anchor="middle">'+t.label+'</text>').join('')+(!all.length?'<text x="330" y="110" text-anchor="middle">해당 단지 시세 이력 미확보</text>':'')+'</svg><div class="market-label" id="provider-point-label">점을 선택하면 기준일과 가격을 확인할 수 있어요.</div>';
  const table=s=>{const fallback=s.id==='naver'?a.url:((a.referenceHistory||[])[0]?.url||''),url=safeurl(s.url||fallback);return '<section><h3 style="color:'+s.color+'">'+s.name+' 기준 가격표</h3><p class="meta">'+esc(s.label||'해당 면적의 원자료 미확보')+'</p><div class="market-table-wrap" style="max-height:340px;overflow:auto"><table class="history" aria-label="'+s.name+' 시세 이력"><thead><tr><th>기준일 / 월</th><th>'+(s.id==='kb'?'일반평균':'범위 중앙값')+'</th>'+(s.id==='naver'?'<th>하한 / 상한</th>':'')+'<th>이전 대비</th></tr></thead><tbody>'+(s.rows.length?[...s.rows].reverse().map((r,i)=>{const prev=s.rows[s.rows.length-i-2],delta=prev?r.price-prev.price:null;return '<tr><td>'+esc(r.period||r.date)+'</td><td>'+money(r.price)+'</td>'+(s.id==='naver'?'<td>'+money(r.low)+' / '+money(r.high)+'</td>':'')+'<td>'+(delta===null?'—':(delta>0?'+':delta<0?'−':'')+money(Math.abs(delta)))+'</td></tr>';}).join(''):'<tr><td colspan="4">과거 시세 원자료 미확보</td></tr>')+'</tbody></table></div><p class="meta">'+esc(s.note||'현재 매물 1건의 호가를 장기 시세로 대신 표시하지 않습니다.')+(url?'<br><a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+s.name+' 원문 확인</a>':'')+'</p></section>';};
  document.getElementById('provider-content').innerHTML='<div class="meta">'+(record?'전용 '+record.area+'㎡ · 매매 시세 · 원자료 확인 '+record.checkedAt:'해당 단지의 동일 면적 시세 원자료 확인 필요')+'</div><div class="price-legend">'+series.map(s=>'<span><i style="background:'+s.color+'"></i>'+s.name+' '+(s.rows.length?s.rows[0].date.slice(0,7)+'~'+s.rows.at(-1).date.slice(0,7):'자료 미확보')+'</span>').join('')+'</div>'+chart+'<p class="coverage">'+(record?'KB는 월별 일반평균, 네이버는 한국부동산원 제공 범위의 중앙값입니다. 서로 다른 조사 기준이며, 네이버의 미확보 과거 구간은 비워 표시합니다.':'네이버·KB 장기 시세는 아직 연결되지 않았습니다. 실거래가나 수동 입력값을 이 두 출처의 시세로 표시하지 않습니다.')+'</p>'+series.map(table).join('');
  document.getElementById('provider-content').querySelectorAll('[data-provider-point]').forEach(p=>{const show=()=>{const s=series.find(s=>s.id===p.dataset.providerPoint),r=s.rows.find(r=>r.date===p.dataset.date);document.getElementById('provider-point-label').textContent=s.name+' · '+(r.period||r.date)+' · '+money(r.price)};p.onfocus=show;p.onclick=show;p.onmouseenter=show;});
 }
 period.onchange=draw;draw();
};
